fn petdex_set_enabled(
    app: AppHandle,
    adapter: State<'_, PetdexAdapter>,
    enabled: bool,
) -> PetdexConnectionStatus {
    adapter.set_enabled(&app, enabled)
}

fn petdex_get_status(adapter: State<'_, PetdexAdapter>) -> PetdexConnectionStatus {
    adapter.status()
}

fn petdex_test_connection(app: AppHandle) -> PetdexConnectionStatus {
    let Some(adapter) = app
        .try_state::<PetdexAdapter>()
        .map(|state| state.inner().clone())
    else {
        return PetdexConnectionStatus::ConnectionError;
    };
    adapter.test_connection().await
}

fn get_system_health(
    app: AppHandle,
    state: State<'_, HealthState>,
) -> Result<SystemHealth, String> {
    let pid = std::process::id();
    let sys_pid = Pid::from_u32(pid);

    let mut sys = state
        .0
        .lock()
        .map_err(|e| format!("health state poisoned: {e}"))?;

    // CPU usage is a delta between refreshes; reusing the managed System makes
    // the first sample 0 and every later sample accurate.
    sys.refresh_cpu_usage();
    sys.refresh_memory();
    sys.refresh_processes_specifics(
        ProcessesToUpdate::Some(&[sys_pid]),
        true,
        ProcessRefreshKind::everything(),
    );

    let app_proc = match sys.process(sys_pid) {
        Some(proc) => AppProcessInfo {
            pid,
            rss_bytes: proc.memory(),
            vsz_bytes: proc.virtual_memory(),
            cpu_percent: proc.cpu_usage() as f64,
            threads: process_thread_count(pid),
            uptime_secs: proc.run_time(),
        },
        None => AppProcessInfo {
            pid,
            rss_bytes: 0,
            vsz_bytes: 0,
            cpu_percent: 0.0,
            threads: None,
            uptime_secs: 0,
        },
    };

    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();

    let system = SystemInfo {
        total_memory_bytes: total_mem,
        used_memory_bytes: used_mem,
        free_memory_bytes: sys.free_memory(),
        memory_usage_percent: usage_percent(used_mem, total_mem),
        total_swap_bytes: total_swap,
        used_swap_bytes: used_swap,
        free_swap_bytes: sys.free_swap(),
        cpu_percent: sys.global_cpu_usage() as f64,
    };

    let app_data_dir = app.path().app_data_dir().unwrap_or_default();
    let disk = disk_info(&app_data_dir);

    let app_info = AppInfo {
        version: app.package_info().version.to_string(),
        platform: std::env::consts::OS.to_string(),
        arch: std::env::consts::ARCH.to_string(),
    };

    Ok(SystemHealth {
        app: app_proc,
        system,
        disk,
        app_info,
    })
}

fn ai_list_routes(
    runtime: State<'_, crate::llm::runtime::LlmRuntime>,
) -> Result<crate::llm::routes::RouteSnapshot, String> {
    Ok(runtime.routes.snapshot()?.as_ref().clone())
}

fn ai_save_routes(
    runtime: State<'_, crate::llm::runtime::LlmRuntime>,
    input: SaveRouteDocumentInput,
) -> Result<crate::llm::routes::RouteSnapshot, String> {
    Ok(runtime
        .routes
        .save(
            input.routes,
            input.default_selection,
            input.expected_revision,
            input.secrets,
        )?
        .as_ref()
        .clone())
}

fn ai_list_route_models(
    runtime: State<'_, crate::llm::runtime::LlmRuntime>,
    route_id: String,
) -> Result<RouteModelsResult, String> {
    let snapshot = runtime.routes.snapshot()?;
    let route = snapshot.route(&route_id)?;
    let models = route
        .model_catalog()?
        .keys()
        .map(|model_id| {
            crate::llm::catalog::resolve(&route.provider(&crate::llm::routes::ModelSelection {
                route_id: route_id.clone(),
                model_id: model_id.clone(),
                reasoning_effort: None,
            })?)
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(RouteModelsResult {
        revision: snapshot.revision,
        models,
    })
}

fn ai_resolve_selection(
    runtime: State<'_, crate::llm::runtime::LlmRuntime>,
    input: ResolveSelectionInput,
) -> Result<crate::llm::catalog::ResolvedModel, String> {
    let snapshot = runtime.routes.snapshot()?;
    let route = snapshot.route(&input.selection.route_id)?;
    if route.revision != input.expected_revision {
        return Err("REVISION_CONFLICT".into());
    }
    crate::llm::catalog::resolve(&route.provider(&input.selection)?)
}

fn ai_list_session_migrations(
    app: tauri::AppHandle,
) -> Result<Vec<SessionMigrationStatus>, String> {
    use tauri::Manager;
    let root = app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("agent-runtime");
    let old = root.join("sessions-v4");
    let new = root.join("sessions-v5");
    if !old.exists() {
        return Ok(vec![]);
    }
    std::fs::read_dir(old)
        .map_err(|e| e.to_string())?
        .filter_map(Result::ok)
        .filter_map(|entry| {
            entry
                .path()
                .file_stem()
                .and_then(|v| v.to_str())
                .map(str::to_string)
        })
        .map(|session_id| {
            validate_provider_id(&session_id)?;
            let status = if new.join(format!("{session_id}.jsonl")).exists() {
                "converted"
            } else if root
                .join("sessions-v4")
                .join(format!("{session_id}.migration.lock"))
                .exists()
            {
                "failed"
            } else {
                "pending"
            };
            Ok(SessionMigrationStatus {
                session_id,
                status: status.into(),
            })
        })
        .collect()
}

fn ai_convert_session_v4_to_v5(
    app: tauri::AppHandle,
    runtime: State<'_, crate::agent_runtime::AgentRuntime>,
    input: ConvertSessionInput,
) -> Result<crate::llm::migration::ConversionResult, String> {
    validate_provider_id(&input.session_id)?;
    use tauri::Manager;
    let root = app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("agent-runtime");
    runtime.convert_v4_session(&root, &input.session_id)
}

fn ai_list_models(
    runtime: State<'_, crate::llm::runtime::LlmRuntime>,
    provider: AiProviderConfig,
) -> Result<Vec<String>, String> {
    validate_provider_config(&provider, false)?;
    let temporary = provider
        .api_key
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let api_key = if temporary.is_some() {
        temporary
    } else {
        let snapshot = runtime.routes.snapshot()?;
        match snapshot.routes.iter().find(|route| route.id == provider.id) {
            Some(route) => runtime.routes.credential(route)?,
            None if provider.requires_api_key => return Err("MISSING_CREDENTIAL".into()),
            None => None,
        }
    };
    crate::llm::discovery::list_models(&provider, api_key).await
}

fn ai_resolve_model(
    provider: AiProviderConfig,
) -> Result<crate::llm::catalog::ResolvedModel, String> {
    validate_provider_config(&provider, true)?;
    crate::llm::catalog::resolve(&provider)
}

fn ai_model_declaration_template(
    provider: AiProviderConfig,
) -> Result<crate::llm::catalog::ModelDefinition, String> {
    crate::llm::catalog::declaration_template(&provider)
}

fn create_session(
    app: AppHandle,
    state: State<'_, SessionManager>,
    pool: State<'_, SftpPool>,
    credentials: State<'_, crate::keychain::CredentialManager>,
